def photo_uri(name):
    for ext in ("jpg", "png"):
        f = f"{HERE}/photos/{name}.{ext}"
        if os.path.exists(f):
            return f"data:image/{'jpeg' if ext == 'jpg' else 'png'};base64," + base64.b64encode(open(f, "rb").read()).decode()
    return None


def prow(items, cls=""):
    cells = ""
    for name, title, sub in items:
        u = photo_uri(name)
        if not u: continue
        cells += f'<div><img src="{u}"><b>{title}</b>{sub}</div>'
    if not cells: return ""
    return f'<div class="prow {cls}">{cells}</div><div class="src" style="margin-bottom:5mm">صور توضيحية مولدة رقمياً لأغراض العرض، وليست من أعمال المكتب.</div>'


def divider(num_, title, text, sid=''):
    art = '<svg style="position:absolute;inset:0;width:100%;height:100%" viewBox="0 0 210 297" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg">'
    for i in range(10):
        r = 26 + i * 12
        art += f'<path d="M{105 - r},172 L{105 - r},{120 - r * .55:.0f} A{r},{r} 0 0 1 {105 + r},{120 - r * .55:.0f} L{105 + r},172" fill="none" stroke="#C97A1E" stroke-opacity="{.55 - i * .05:.2f}" stroke-width=".35"/>'
    for i in range(22):
        art += f'<line x1="0" x2="210" y1="{i * 8}" y2="{i * 8}" stroke="#fff" stroke-opacity=".03" stroke-width=".3"/>'
    art += '<rect x="0" y="172" width="210" height="125" fill="#0E2740"/></svg>'
    return f'<div class="divider" id="{sid}">{art}<div class="bar"></div><div class="dn">{num_:02d}</div><h1>{title}</h1><p>{text}</p></div>'


